import test from 'node:test';
import assert from 'node:assert/strict';
import { attachAudienceSignal, attachPdfArtifact, buildCompanyHistory, buildCompanyPageViewModel, buildCompanyProfile, buildEventProfile, buildInstitutionProfile, buildMarketProfile, buildOperatorPackage, buildPeriodicLibraryAdapter, buildThemeHistory, buildThemeProfile, buildTopicPageViewModel, createEvidenceEdge, generateEvergreenCandidates, getCanonicalRegistry, getCompaniesByPeriod, getEventsByPeriod, getInstitutionViewsByPeriod, getMarketReactionsByPeriod, getThemesByPeriod, ingestNewsletter, recordDecision, resolveCanonical, searchLibrary } from '../src/library/content-library.js';
import { buildVerifiedProductionLibrary, ingestDailyOperationsAudit } from '../src/library/production-library.js';
import { buildGoldenIntelligenceRehearsal } from '../src/intelligence/golden-rehearsal.js';
import { DailyProductionOrchestrator } from '../src/operations/daily-orchestrator.js';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { readLibrary, writeLibrary } from '../src/library/storage.js';
const built = () => buildVerifiedProductionLibrary('2026-10-02T09:00:00+09:00');
test('stable canonical ids and aliases normalize NVIDIA variants', () => {
    for (const alias of ['NVIDIA', 'Nvidia', 'NVIDIA Corp.', 'NVDA'])
        assert.equal(resolveCanonical('company', alias).canonicalId, 'company:nvidia');
    assert.equal(getCanonicalRegistry('company').find(x => x.canonicalId === 'company:nvidia')?.redirectTo, null);
});
test('ambiguous canonical merge remains REVIEW_REQUIRED', () => assert.deepEqual(resolveCanonical('company', 'Samsung'), { canonicalId: null, status: 'REVIEW_REQUIRED', candidates: ['company:samsung-electronics', 'institution:samsung-securities'] }));
test('verified production ingestion creates content library records', () => { const x = built(); assert.ok(x.store.records.length > 20); assert.equal(x.store.schemaVersion, '1.0.0'); assert.equal(x.operator.counts.events, 6); });
test('source, event, and entity dedupe stay separate', () => { const x = built(); assert.ok(x.ingestions.reduce((n, i) => n + i.sourceDuplicates, 0) > 0); assert.ok(new Set(x.store.records.filter(r => r.recordType === 'SOURCE').map(r => r.canonicalId)).size > 1); assert.equal(new Set(x.store.records.filter(r => r.recordType === 'EVENT').map(r => r.canonicalId)).size, x.operator.counts.events); });
test('re-ingestion is idempotent and preserves stable IDs', () => { const x = built(); const model = buildGoldenIntelligenceRehearsal().newsletter; const again = ingestNewsletter(x.store, model, { observedAt: '2026-10-02T10:00:00+09:00', publicationId: 'motus-daily-intelligence-2026-09-29', publicationTitle: model.title }); assert.equal(again.store.records.length, x.store.records.length); assert.deepEqual(again.store.records.map(r => r.libraryId).sort(), x.store.records.map(r => r.libraryId).sort()); });
test('company profile traces events, themes, research, and provenance', () => { const p = buildCompanyProfile(built().store, 'company:microsoft'); assert.ok(p.themeIds.includes('theme:ai-for-science')); assert.ok(p.relatedEvents.length); assert.ok(p.sourceRefs.length); assert.ok(p.originRecordIds.length); });
test('theme profile traces companies, events, publications, and evidence', () => { const p = buildThemeProfile(built().store, 'theme:agentic-ai'); assert.ok(p.relatedCompanyIds.includes('company:openai')); assert.ok(p.relatedEventIds.length); assert.ok(p.publications.length); assert.ok(p.supportingEvidence.length); });
test('event profile reuses canonical event and keeps source provenance', () => { const p = buildEventProfile(built().store, 'event:openai-dots-2026-09-29'); assert.equal(p.eventId, 'event:openai-dots-2026-09-29'); assert.ok(p.themeIds.includes('theme:agentic-ai')); assert.ok(p.primarySources.length); });
test('institution profile contains only evidence-backed research stance', () => { const p = buildInstitutionProfile(built().store, 'institution:samsung-securities'); assert.equal(p.institutionType, 'BROKERAGE'); assert.equal(p.researchRecords.length, 5); assert.equal(p.stanceHistory.length, 5); });
test('market profiles support US Korea and Global with preserved snapshots', () => { const s = built().store; const us = buildMarketProfile(s, 'market:us'); assert.equal(us.marketId, 'market:us'); assert.equal(us.historicalSnapshots.length, 2); assert.ok(buildMarketProfile(s, 'market:korea').marketFacts.length); assert.equal(buildMarketProfile(s, 'market:global').marketId, 'market:global'); });
test('relationship rejects missing evidence and source refs', () => assert.throws(() => createEvidenceEdge({ fromId: 'a', toId: 'b', relationshipType: 'COMPANY_HAS_THEME', reason: 'keyword only', evidenceRefs: [], sourceRefs: [], originRecordIds: [], createdAt: '2026-10-02T00:00:00Z' }), /evidence/));
test('all production relationships carry traceability', () => assert.ok(built().store.edges.every(edge => edge.sourceRefs.length + edge.evidenceRefs.length > 0 && edge.originRecordIds.length > 0)));
test('weekly period queries use structured library records', () => { const s = built().store; assert.ok(getEventsByPeriod(s, '2026-09-28', '2026-10-04').length); assert.ok(getCompaniesByPeriod(s, '2026-09-28', '2026-10-04').length); assert.ok(getThemesByPeriod(s, '2026-09-28', '2026-10-04').length); });
test('monthly compatibility adapter exposes institution and market inputs', () => { const a = buildPeriodicLibraryAdapter(built().store, '2026-09-01', '2026-09-30'); assert.equal(a.institutionViews.length, getInstitutionViewsByPeriod(built().store, '2026-09-01', '2026-09-30').length); assert.equal(a.marketReactions.length, getMarketReactionsByPeriod(built().store, '2026-09-01', '2026-09-30').length); });
test('theme history does not infer change without prior period', () => assert.equal(buildThemeHistory(built().store, 'theme:agentic-ai', '2026-09-29', '2026-09-30').changeState, null));
test('theme history records actual change when prior data exists', () => { const s = built().store; const current = buildThemeHistory(s, 'theme:agentic-ai', '2026-09-29', '2026-09-30'); const prior = { ...current, periodStart: '2026-09-22', periodEnd: '2026-09-28', eventCount: 0, changeState: null }; assert.equal(buildThemeHistory(s, 'theme:agentic-ai', '2026-09-29', '2026-09-30', prior).changeState, 'NEW'); });
test('company history needs prior data before attention change', () => { const current = buildCompanyHistory(built().store, 'company:openai', '2026-09-29', '2026-09-30'); assert.equal(current.attentionChange, null); assert.equal(buildCompanyHistory(built().store, 'company:openai', '2026-09-29', '2026-09-30', { ...current, events: [], researchMentions: [], attentionChange: null }).attentionChange, 'NEW'); });
test('evergreen candidates remain behind review gate', () => { const candidates = generateEvergreenCandidates(built().store); assert.ok(candidates.length); assert.ok(candidates.every(c => c.candidateState === 'REVIEW_REQUIRED')); assert.ok(candidates.every(c => c.sourceCount >= 2)); assert.ok(candidates.every(c => !('score' in c))); });
test('topic page boundary contains timeline and source trace', () => { const page = buildTopicPageViewModel(built().store, 'theme:agentic-ai'); assert.ok(page.latestEvents.length); assert.ok(page.timeline.length); assert.ok(page.sources.length); });
test('company page boundary links reports without publishing them', () => { const page = buildCompanyPageViewModel(built().store, 'company:openai'); assert.equal(page.company.companyId, 'company:openai'); assert.ok(page.relatedReports.every(report => report.publicUrl === null)); });
test('searchLibrary filters text record and linked entity', () => { const s = built().store; assert.ok(searchLibrary(s, { text: 'OpenAI' }).length); assert.ok(searchLibrary(s, { recordType: 'RESEARCH', institution: 'institution:samsung-securities' }).length); assert.ok(searchLibrary(s, { theme: 'theme:agentic-ai', dateRange: { from: '2026-09-29', to: '2026-09-30' } }).length); });
test('provenance survives JSON round trip', () => { const s = built().store; const round = JSON.parse(JSON.stringify(s)); const event = buildEventProfile(round, 'event:openai-dots-2026-09-29'); assert.ok(event.sourceRefs.length && event.evidenceRefs.length && event.originRecordIds.length); });
test('rejected decision does not promote origin records', () => { const s = built().store; const rejected = recordDecision(s, { originRecordId: 'motus-ai-intelligence-2026-09-29', decision: 'REJECTED', reason: 'human editorial rejection', at: '2026-10-02T10:00:00+09:00' }); assert.ok(rejected.decisions.some(d => d.decision === 'REJECTED')); assert.equal(rejected.records.filter(r => r.recordType !== 'SOURCE' && r.originRecordIds.includes('motus-ai-intelligence-2026-09-29')).length, 0); });
test('operator package preserves count ties and records zero external actions', () => { const x = built(); const op = buildOperatorPackage(x.store, { newRecordIds: [], updatedRecordIds: [], reviewRequired: [] }); assert.equal(op.externalActions.bloggerInsert, 0); assert.equal(op.externalActions.driveUpload, 0); assert.equal(op.commerce.enabled, false); assert.equal(op.counts.relationships, x.store.edges.length); });
test('audience metrics remain audience signals and do not alter records', () => { const s = built().store; const before = JSON.stringify(s.records); const next = attachAudienceSignal(s, { publicationId: 'motus-ai-intelligence-2026-09-29', observedAt: '2026-10-02T00:00:00Z', impressions: 10, clicks: 2, source: 'Search Console' }); assert.equal(JSON.stringify(next.records), before); assert.equal(next.audienceSignals.length, 1); });
test('PDF relation supports internal entity links and no public URL', () => { const s = built().store; const next = attachPdfArtifact(s, { artifactId: 'report:test', path: 'data/reports/test.pdf', publicationId: 'motus-ai-intelligence-2026-09-29', companyIds: ['company:openai'], themeIds: ['theme:agentic-ai'], eventIds: ['event:openai-dots-2026-09-29'], publicUrl: null, createdAt: '2026-10-02T00:00:00Z' }); assert.equal(next.pdfArtifacts.find(a => a.artifactId === 'report:test')?.publicUrl, null); });
test('production library has no public actions, URLs, or commerce activation', () => { const x = built(); assert.deepEqual(x.operator.externalActions, { bloggerInsert: 0, bloggerPatch: 0, bloggerPublish: 0, driveUpload: 0, publicPdfShare: 0 }); assert.equal(x.operator.commerce.enabled, false); assert.ok(x.store.pdfArtifacts.every(a => a.publicUrl === null)); });
test('DailyProductionOrchestrator decision trail adapter preserves selected audit', async () => { const run = await new DailyProductionOrchestrator().run({ runDate: '2026-10-01', categories: ['AI_INTELLIGENCE'], generatedAt: '2026-10-01T09:00:00+09:00' }); const store = ingestDailyOperationsAudit(built().store, run); assert.ok(store.decisions.some(item => item.originRecordId.startsWith('candidate:') && item.decision === 'SELECTED')); });
test('local persistent store writes schema-versioned migration-friendly partitions', async () => { const x = built(); const root = join(await mkdtemp(join(tmpdir(), 'motus-library-')), 'data', 'library'); const files = await writeLibrary(root, x.store, x.operator); assert.ok(files.some(file => file.endsWith('registry\\companies.json') || file.endsWith('registry/companies.json'))); assert.equal((await readLibrary(root))?.schemaVersion, '1.0.0'); });
